mapper.select:
select SEQNO as seqno,
		PORTFOLIO_ID as portfolioId,
		ACCT_ID as acctId,
		ADJ_DATE as adjDate,
		CCY as ccy,
		ADJ_AMT as adjAmt  
	from CASH_ART_DEAL t 
	where t.portfolio_id = #{portfolioId} 
			AND t.acct_id = #{acctId} 
			AND t.adj_date = #{adjDate,jdbcType=DATE} 
			AND t.ccy = #{ccy}
